 let revealTimer=null;
 const revealDelays=[1500,750,375];
 function cancelReveal(){if(revealTimer!==null)clock.clearTimeout(revealTimer);revealTimer=null;}
 function revealActive(){return ui.reveal&&(ui.reveal.kind==='league'?ui.view==='leagueDraw':ui.reveal.kind==='draft'?ui.view==='draftDraw':ui.view==='dynasty'&&s.dynasty.offseason?.phase==='lottery');}
 function scheduleReveal(){
  cancelReveal();const r=ui.reveal;if(!r||!r.running||r.count>=8||!revealActive())return;
  revealTimer=clock.setTimeout(()=>{revealTimer=null;if(!revealActive()||!ui.reveal.running)return;ui.reveal.count=Math.min(8,ui.reveal.count+1);ui.revealed=ui.reveal.count;if(ui.reveal.count===8)ui.reveal.running=false;render(false);save();scheduleReveal();},revealDelays[r.speedIndex]);
 }
 function startReveal(kind,snapshot=null){cancelReveal();ui.reveal={kind,count:snapshot?.count||0,speedIndex:snapshot?.speedIndex||0,running:snapshot?.running??true};ui.revealed=ui.reveal.count;scheduleReveal();}
 function finishReveal(){cancelReveal();ui.reveal=null;}
 bind('world',['story'],()=>{assert(ui.newCareer||!X.hasStoredSave(),'Another open game has started a career. Return home and choose Continue, or confirm Start again.');cancelMatchTimer();ui.match=null;finishReveal();read.fresh();ui.newCareer=false;G.skipLeagueReveal();ui.revealed=0;setView('leagueDraw');startReveal('league');render(false);save();});
 bind('revealClub',['leagueDraw'],()=>{assert(revealActive(),'Open the reveal first.');ui.reveal.count=Math.min(8,ui.reveal.count+1);ui.revealed=ui.reveal.count;if(ui.reveal.count===8)ui.reveal.running=false;scheduleReveal();});
 bind('revealAll',['leagueDraw','draftDraw','dynasty'],()=>{assert(revealActive(),'Open the order reveal first.');cancelReveal();ui.reveal.count=8;ui.revealed=8;ui.reveal.running=false;});
 bind('revealRun',['leagueDraw','draftDraw','dynasty'],()=>{assert(revealActive()&&ui.reveal.count<8,'The reveal is complete.');ui.reveal.running=!ui.reveal.running;scheduleReveal();});
 bind('revealSpeed',['leagueDraw','draftDraw','dynasty'],()=>{assert(revealActive(),'Open the reveal first.');ui.reveal.speedIndex=(ui.reveal.speedIndex+1)%3;scheduleReveal();});
 bind('clubs',['leagueDraw'],()=>{assert(ui.reveal?.count===8,'Reveal the clubs first.');finishReveal();G.finishLeagueReveal();setView('clubs');});
 bind('club',['clubs'],i=>{assert(Number.isInteger(i)&&i>=0&&i<s.league.length,'Choose one of the eight clubs.');G.selectClub(i);const c=s.league[i];modal(c.name,X.clubBrief(c)+`<div class="g8actions g8clubconfirm">${btn('Take over this club','confirmClub',[],'g8primary')}</div>`,'club');});
 bind('confirmClub',['clubs'],()=>{assert(!s.userClub,'Your club has already been chosen.');assert(s.selectedClub!==null,'Choose a club.');G.confirmClub();setView('recruit');});
 function restorePresentation(){cancelReveal();ui.reveal=null;clock.resume();const savedReveal=s.dynasty.v8Reveal,view=X.screen();setView(view==='world'?'clubs':view);if(savedReveal&&savedReveal.year===s.year&&savedReveal.count<=8){if(savedReveal.kind==='league'){setView('leagueDraw');startReveal('league',savedReveal);}else if(savedReveal.kind==='draft'){window.GCC8_FOUNDATION_READ.pauseDraft();setView('draftDraw');startReveal('draft',savedReveal);}else if(savedReveal.kind==='annual'&&s.dynasty.offseason?.phase==='lottery'){setView('dynasty');startReveal('annual',savedReveal);}render(false);}else if(view==='dynasty'&&s.dynasty.offseason?.phase==='lottery'){startReveal('annual',{count:8,running:false});render(false);}const savedUI=s.dynasty.v8UI;if(savedUI){ui.teamReturn=savedUI.teamReturn;ui.seasonTab=savedUI.seasonTab;ui.result=s.results.find(r=>r.round===savedUI.resultRound)||null;archiveReturn=views[savedUI.archiveReturn]?savedUI.archiveReturn:'season';if(savedUI.view==='team'&&s.fullSchedule.length){G.go('team');setView('team');}else if(savedUI.view==='result'&&!savedUI.resultFinal){ui.result=s.results.find(r=>r.round===savedUI.resultRound);if(ui.result)setView('result');}else if(savedUI.view==='archive')setView('archive');render(false);}else if(view==='archive')archiveReturn=s.dynasty.careerClosed?'legacy':s.dynasty.offseason?'dynasty':s.dynasty.archiveReturnScreen||'season';cancelMatchTimer();ui.match=null;const savedMatch=s.dynasty.v8Match;if(savedMatch&&savedMatch.year===s.year){const r=matchFromReference(savedMatch.reference);if(r){ui.match={...savedMatch};ui.result=r;if(savedUI?.view==='matchReveal')beginMatch(r,savedMatch.returnView,savedMatch);}}if(annual())D.runCpuDraftUntilUser(false);}
 bind('continue',['home'],()=>{assert(X.hasSave(),'There is no saved dynasty.');ui.draftShown=X.draftPageSize();if(!X.hasStoredSave()&&s.dynasty?.started){setView(views[ui.resumeView]?ui.resumeView:'team');announce('Continuing this session. This browser has not saved your progress.');return;}assert(D.resumeSave()===true,'The save could not be restored. Your saved data has been kept.');restorePresentation();});
 const guideCard=(icon,title,copy,number='')=>`<section class="g8guidecard"><div class="g8guidecardhead">${number?`<span class="g8guidenumber">${number}</span>`:X.icon(icon)}<h3>${title}</h3></div><p>${copy}</p></section>`;
 const guideFooter=active=>`<footer class="g8guidefooter"><nav aria-label="Game guides">${[['how','How to play'],['howItWorks','How it works'],['breakawayStory','The breakaway story']].map(([key,label])=>btn(label,key,[],`g8ghost ${key===active?'g8guidecurrent':''}`,key===active).replace('type="button"',`type="button" ${key===active?'aria-current="page"':''}`)).join('')}</nav>${btn('Back to game','close',[],'g8primary')}</footer>`;
 const guideIntro=(eyebrow,title,copy)=>`<header class="g8guideintro"><span class="g8eyebrow">${eyebrow}</span><h3>${title}</h3>${copy?`<p>${copy}</p>`:''}</header>`;
 bind('how','*',()=>modal('How to play',`<article class="g8guide g8playguide">${guideIntro('YOUR FIRST SEASON','From the draft to the final.','Build your squad, name your XI and take your club through the season.')}<div class="g8guidegrid">${[
 ['Choose your club','Read the home-ground conditions and choose one of the eight clubs.'],
 ['Watch league signings','The five-day window decides who enters the league. These players join the draft pool, not your club. Use speed or skip to move ahead.'],
 ['Draft your fifteen','Scout a player by opening their card, then select Pick. The order reverses each round. Your home ground and the jobs players can fill matter.'],
 ['Name your XI','Select eleven from your squad. Open a selected player to move them up or down the batting order; use Swap to change the side.'],
 ['Play the season','Play fourteen league matches. Follow the over-by-over feed or skip to the result. The top four reach two semi-finals and a Grand Final.'],
 ['Build again','Your squad carries over. Review retirements and development, make any optional changes, then draft the vacancies and name your next XI.']
 ].map(([title,copy],i)=>guideCard('stumps',title,copy,i+1)).join('')}</div><div class="g8guiderules">${X.disclosure('Retirements, releases & draft picks',`<div class="g8rulegrid">${guideCard('stumps','Who stays','Players stay automatically unless they retire, are traded out or you confirm a release. You can release at most two players, subject to the departure allowance.')}${guideCard('cricket','The departure allowance','Retirements are uncapped. They use the four-departure allowance before optional releases and outgoing trades. Three retirements leave room for one voluntary departure; four or more leave none. Incoming players do not restore the allowance.')}${guideCard('cricket-ball','Fill the vacancies','A fresh draft order is drawn each year, regardless of league finish. Draft back to fifteen players. Supplementary picks fill remaining vacancies at the end, continuing the snake order.')}</div>`)}${X.disclosure('Trading rules',`<div class="g8rulegrid">${guideCard('cricket','Windows & limits','No trades in 2008. From 2009, each club can complete two trades per season. The in-season window closes when Round 3 is complete; offseason trading closes when the draft begins.')}${guideCard('cricket-ball','Build a deal','Each side can include up to two players and two picks. Only owned Round 1 and Round 2 picks can be traded, after the offseason order draw. In-season deals exchange equal numbers of players, with no picks.')}</div>`)}${X.disclosure('Ties, saves & career length',`<div class="g8rulegrid">${guideCard('cricket-ball','Super Overs','A tied match goes to a simplified Super Over: six legal balls or two wickets. Tied Super Overs repeat. The game selects the batters and bowler from each XI; tie-break figures stay separate from season statistics.')}${guideCard('stumps','Your career','Play from 2008 through the final season in 2026. Progress autosaves in this browser. If a save warning appears, keep the game open. There are no wages or salary cap to manage.')}</div>`)}</div></article>${guideFooter('how')}`,'how'));
 bind('howItWorks','*',()=>modal('How it works',`<article class="g8guide g8worksguide">${guideIntro('THE CRICKET BEHIND YOUR DECISIONS','Build a side that fits the contest.','Ratings help you judge your options. Selection, conditions and chance shape what happens.')}<div class="g8guidegrid">${[
 ['cricket','Read the player’s job','Overall summarises current ability. Batting position and detailed skills help you judge a particular job. Team ratings describe the XI, not a predicted score.'],
 ['stumps','Make selection count','Your eleven and batting order matter. A keeper, enough credible bowling and batters suited to their positions give the side options. There is no fixed XI recipe.'],
 ['cricket-ball','Read the ground','Pace and carry, spin and grip, boundary size and match conditions change the contest. A side built for one ground may need a different balance elsewhere.'],
 ['cricket-ball','Allow for uncertainty','Matches are simulated delivery by delivery. Ability, form, conditions and the match situation influence outcomes. A stronger side has an advantage, not a guarantee.'],
 ['cricket','Use the scorebook','The feed shows each over and the key moments. Open the scorebook for the full result. Look for patterns across matches before judging a player or changing your plan.'],
 ['stumps','Think beyond this season','Players develop, age and retire. Skills can change even when overall stays level. Scouting outlooks are estimates; development reports show the changes that have happened.']
 ].map(([icon,title,copy])=>guideCard(icon,title,copy)).join('')}</div><p class="g8guidenote">Speed and skip change the presentation, not your players’ ability or the match result.</p></article>${guideFooter('howItWorks')}`,'howItWorks'));
 bind('breakawayStory','*',()=>modal('The breakaway story',`<article class="g8guide g8breakawayguide">${guideIntro('AN ALTERNATE CRICKET HISTORY · 2008','One offer. Eight clubs. A new balance of power.','Twenty20 has changed the sound of cricket. Now Saudi-backed investors want to change who runs it.')}<p class="g8storyopening">Eight clubs leave their domestic competitions for one global T20 league. They bring their colours, their grounds and their supporters. The playing lists are another matter.</p><div class="g8storychapters">${[
 ['cricket-ball','Five days to choose a side','The established competitions still have their pull. So does the promise of a new stage. For five days, players decide whether to enter the breakaway. Until the window closes, nobody knows how strong the draft pool will be.'],
 ['cricket','Build an eleven worth watching','Fifteen places in your squad. Seven rivals reading the same board. The opener, the death bowler, the keeper: every pick shapes the side. A famous name is only a start. Your ground, your balance and your XI decide what follows.'],
 ['stumps','Make the years count','Fourteen league matches lead to the finals. Beyond them, players develop, veterans retire and the next draft brings another judgement call. From 2008 to the final season in 2026, the challenge is to build a club that lasts.']
 ].map(([icon,title,copy])=>guideCard(icon,title,copy)).join('')}</div><p class="g8guideclosing">The league has made its break. What will your club make of it?</p></article>${guideFooter('breakawayStory')}`,'breakawayStory'));
